CREATE TABLE "QUALITY_CONC_HML"."ADIANTAMENTO_SOLICITACAO" (
    "IDADIANTAMENTO" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DEPARTAMENTO" INTEGER NOT NULL,
    "IDEMPRESA" INTEGER NOT NULL,
    "NUCNPJEMPRESA" NVARCHAR(18) NOT NULL,
    "POSSUINOTAFISCAL" NVARCHAR(1) NOT NULL,
    "CNPJFATURAMENTO" NVARCHAR(18) NOT NULL,
    "VRSOLICITADO" DECIMAL(18,2) NOT NULL,
    "DESCRICAO" NVARCHAR(2000) NOT NULL,
    "ANEXOORCAMENTO" NVARCHAR(500),
    "ANEXONOTAFISCAL" NVARCHAR(500),
    "STATUS" NVARCHAR(30) NOT NULL DEFAULT 'EM ANDAMENTO',
    "DSJUSTIFICATIVA" NVARCHAR(2000),
    "IDUSUARIOCRIACAO" INTEGER NOT NULL,
    "DATACRIACAO" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IDUSUARIOALTERACAO" INTEGER,
    "DATAALTERACAO" TIMESTAMP,
    "DATAFINALIZACAO" TIMESTAMP,
    "STATIVO" NVARCHAR(5) NOT NULL DEFAULT 'True'
);


CREATE TABLE "QUALITY_CONC_HML"."ADIANTAMENTO_PAGAMENTO" (
    "IDPAGAMENTO" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IDADIANTAMENTO" INTEGER NOT NULL,
