    "ANEXOCOMPROVANTE" NVARCHAR(500),
    "DSOBSERVACAO" NVARCHAR(1000),
    "IDUSUARIOCRIACAO" INTEGER NOT NULL,
    "DATACRIACAO" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "STATIVO" NVARCHAR(5) NOT NULL DEFAULT 'True'
);

CREATE TABLE "QUALITY_CONC_HML"."ADIANTAMENTO_HISTORICO" (
    "IDHISTORICO" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IDADIANTAMENTO" INTEGER NOT NULL,
    "STATUSANTERIOR" NVARCHAR(30),
    "STATUSNOVO" NVARCHAR(30),
    "ACAO" NVARCHAR(50) NOT NULL,
    "DSOBSERVACAO" NVARCHAR(2000),
    "IDUSUARIO" INTEGER NOT NULL,
    "DATAACAO" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

